CodeExamples:
```csharp
// Trong .NET 6+, PriorityQueue đã được hỗ trợ sẵn
PriorityQueue<string, int> pq = new PriorityQueue<string, int>();

// Thêm vào PQ kèm độ ưu tiên (số nhỏ ưu tiên cao -> Min Heap)
pq.Enqueue("Bệnh nhân ho nhẹ", 3);
pq.Enqueue("Bệnh nhân cấp cứu", 1);
pq.Enqueue("Bệnh nhân gãy tay", 2);

// Lấy ra
while(pq.Count > 0) {
    Console.WriteLine(pq.Dequeue());
    // Kết quả: Cấp cứu -> Gãy tay -> Ho nhẹ
}
```
